checkArgument() {
  firstChar=$(echo "$1" | cut -c1-1)
  if [ "$firstChar" = '' ] || [ "$firstChar" = '-' ]; then
    printHelpAndExit
  fi
}

checkCmd() {
  if ! "$@"; then
    echo "Error - command failed: $*"
    exit 1
  fi
}

haveCmd() {
  command -v "$1" >/dev/null 2>&1
}

base64DecodeCmd() {
  # Writes decoded bytes to stdout.
  if haveCmd base64; then
    base64 -d
  else
    python3 - <<'PY'
import sys, base64
sys.stdout.buffer.write(base64.b64decode(sys.stdin.buffer.read()))
PY
  fi
}

base64EncodeCmd() {
  # Reads bytes from stdin, writes base64 text to stdout.
  if haveCmd base64; then
    # -w0 disables wrapping (GNU coreutils). If unavailable, fall back.
    if base64 -w0 </dev/null >/dev/null 2>&1; then
      base64 -w0
    else
      base64
    fi
  else
    python3 - <<'PY'
import sys, base64
sys.stdout.write(base64.b64encode(sys.stdin.buffer.read()).decode('ascii'))
PY
  fi
}

repackInstallerFromLibDirOrExit() {
  # $1: directory containing libur*.so* files
  libDir="$1"
  if [ "$libDir" = '' ] || [ ! -d "$libDir" ]; then
    echo "Error: pack directory '$libDir' does not exist."
    exit 1
  fi

  fullScriptPath=$(readlink -f "$0")

  # Binary-safe marker line lookup.
  markerLine=$(grep -a -n '^__ARCHIVE__$' "$fullScriptPath" | head -n 1 | cut -d: -f1)
  if [ "$markerLine" = '' ]; then
    echo "Error: __ARCHIVE__ marker not found in installer."
    exit 1
  fi

  tmpRoot=$(mktemp -d /tmp/oneapi_installer_pack.XXXXXX)
  stageDir="$tmpRoot/stage"
  payload="$tmpRoot/payload.tgz"
  newScript="$tmpRoot/installer.new"

  checkCmd 'mkdir' '-p' "$stageDir/lib"

  # Ensure we have at least one match before copying.
  set -- "$libDir"/libur*.so*
  if [ ! -e "$1" ]; then
    echo "Error: no files matching '$libDir/libur*.so*' found."
    exit 1
  fi

  # Preserve symlinks and modes.
  checkCmd 'cp' '-a' "$libDir"/libur*.so* "$stageDir/lib/"

  (cd "$stageDir" && checkCmd 'tar' '-czf' "$payload" '.')
  # archiveChecksum always refers to the decoded payload bytes.
  newChecksum=$(sha384sum "$payload" | awk '{ print $1 }')

  # Rewrite the script header (up to and including __ARCHIVE__) and patch the checksum.
  awk -v marker="$markerLine" -v sum="$newChecksum" '
    NR > marker { exit }
    /^archiveChecksum=/ { print "archiveChecksum=\x27" sum "\x27"; next }
    { print }
  ' "$fullScriptPath" > "$newScript"

  # Append the new payload in base64 to keep the installer text-safe.
  cat "$payload" | base64EncodeCmd >> "$newScript"
  printf '\n' >> "$newScript"

  # Keep permissions roughly consistent.
  if ! chmod --reference="$fullScriptPath" "$newScript" 2>/dev/null; then
    chmod +x "$newScript"
  fi

  backup="$fullScriptPath.bak.$(date +%Y%m%d_%H%M%S)"
  checkCmd 'cp' '-a' "$fullScriptPath" "$backup"
  checkCmd 'mv' "$newScript" "$fullScriptPath"

  # Verify that the embedded checksum matches the new archive.
  archiveStart=$(awk '/^__ARCHIVE__/ {print NR + 1; exit 0; }' "$fullScriptPath")
  actual=$(tail "-n+$archiveStart" "$fullScriptPath" | base64DecodeCmd | sha384sum | awk '{ print $1 }')
  if [ "$actual" != "$newChecksum" ]; then
    echo "Error: repack verification failed."
    echo "Expected checksum: $newChecksum"
    echo "Actual checksum:   $actual"
    echo "Backup left at: $backup"
    exit 1
  fi

  echo "Repacked embedded archive successfully."
  echo "Updated: $fullScriptPath"
  echo "Backup:  $backup"
  echo
}

resolvePayloadFileOrExit() {
  if resolvedPath=$(resolvePayloadFile "$1"); then
    echo "$resolvedPath"
    return 0
  fi

  echo "Error: required file '$1' not found in payload directories:"
  echo "* $payloadDir"
  if [ "$payloadDirFallback" != '' ]; then
    echo "* $payloadDirFallback"
  fi
  exit 1
}

resolvePayloadFile() {
  # $1: filename to find within payloadDir/payloadDirFallback
  # Searches common install layouts.
  fileName="$1"
  for candidate in \
    "$payloadDir/$fileName" \
    "$payloadDir/lib/$fileName" \
    "$payloadDir/lib64/$fileName" \
    "$payloadDir/share/$fileName" \
    "$payloadDir/share/doc/$fileName" \
    "$payloadDir/share/licenses/$fileName" \
    "$payloadDir/licenses/$fileName"; do
    if [ -f "$candidate" ]; then
      echo "$candidate"
      return 0
    fi
  done

  if [ "$payloadDirFallback" != '' ]; then
    for candidate in \
      "$payloadDirFallback/$fileName" \
      "$payloadDirFallback/lib/$fileName" \
      "$payloadDirFallback/lib64/$fileName" \
      "$payloadDirFallback/share/$fileName" \
      "$payloadDirFallback/share/doc/$fileName" \
      "$payloadDirFallback/share/licenses/$fileName" \
      "$payloadDirFallback/licenses/$fileName"; do
      if [ -f "$candidate" ]; then
        echo "$candidate"
        return 0
      fi
    done
  fi

  return 1
}

extractPackage() {
  # Prefer using already-built install artifacts if present.
  # This avoids relying on the embedded archive during local development.
  if [ "$extractOnly" = 'no' ] && [ "$llvmInstallDir" != '' ] && [ -d "$llvmInstallDir" ]; then
    payloadDir=$(readlink -f "$llvmInstallDir")
    cleanupPayloadDir='no'

    # If the local install tree is missing required binaries, fall back to the
    # embedded archive for just the missing pieces.
    needFallback='no'
    if [ ! -f "$payloadDir/$urAdapterVersioned" ] && [ ! -f "$payloadDir/lib/$urAdapterVersioned" ] && [ ! -f "$payloadDir/lib64/$urAdapterVersioned" ]; then
      needFallback='yes'
    fi

    if [ "$needFallback" = 'no' ]; then
      return
    fi
    # Continue to extract embedded archive below and use it as a fallback.
  fi

  fullScriptPath=$(readlink -f "$0")
  archiveStart=$(awk '/^__ARCHIVE__/ {print NR + 1; exit 0; }' "$fullScriptPath")

  # The embedded archive may be either raw gzip-compressed tar (legacy) or
  # base64-encoded gzip-compressed tar (text-safe).
  magic=$(tail "-n+$archiveStart" "$fullScriptPath" | head -c 2 | od -An -tx1 | tr -d ' \n')
  if [ "$magic" = '1f8b' ]; then
    checksum=$(tail "-n+$archiveStart" "$fullScriptPath" | sha384sum | awk '{ print $1 }')
    extractCmd='tar -xz -C'
    extractPipe='cat'
  else
    checksum=$(tail "-n+$archiveStart" "$fullScriptPath" | base64DecodeCmd | sha384sum | awk '{ print $1 }')
    extractCmd='tar -xz -C'
    extractPipe='base64DecodeCmd'
  fi
  if [ "$checksum" != "$archiveChecksum" ]; then
    echo "Error: archive corrupted!"
    echo "Expected checksum: $archiveChecksum"
    echo "Actual checksum: $checksum"
    echo "If you edited this installer in a text editor, the embedded archive may have been corrupted."
    echo "Please re-create or re-download this installer and try again."
    echo
    exit 1
  fi

  if [ "$tempDir" = '' ]; then
    tempDir=$(mktemp -d /tmp/oneapi_installer.XXXXXX)
  else
    checkCmd 'mkdir' '-p' "$tempDir"
    tempDir=$(readlink -f "$tempDir")
  fi

  if [ "$extractPipe" = 'cat' ]; then
    tail "-n+$archiveStart" "$fullScriptPath" | tar -xz -C "$tempDir"
  else
    tail "-n+$archiveStart" "$fullScriptPath" | base64DecodeCmd | tar -xz -C "$tempDir"
  fi
  if [ "$payloadDir" != '' ] && [ "$cleanupPayloadDir" = 'no' ]; then
    payloadDirFallback="$tempDir"
    cleanupPayloadDirFallback='yes'
  else
    payloadDir="$tempDir"
    cleanupPayloadDir='yes'
  fi
}

findOneapiRootOrExit() {
  for path in "$@"; do
    if [ "$path" != '' ] && [ -d "$path/compiler" ]; then
      if [ -d "$path/compiler/$oneapiVersion" ]; then
        echo "Found oneAPI DPC++/C++ Compiler $oneapiVersion in $path/."
        echo
        oneapiRoot=$path
        return
      else
        majCompatibleVersion=$(ls "$path/compiler" | grep "${oneapiVersion%.*}" | head -n 1)
        if [ "$majCompatibleVersion" != '' ] && [ -d "$path/compiler/$majCompatibleVersion" ]; then
          echo "Found oneAPI DPC++/C++ Compiler $majCompatibleVersion in $path/."
          echo
          oneapiRoot=$path
          oneapiVersion=$majCompatibleVersion
          return
        fi
      fi
    fi
  done

  echo "Error: Intel oneAPI DPC++/C++ Compiler $oneapiVersion was not found in"
  echo "any of the following locations:"
  for path in "$@"; do
    if [ "$path" != '' ]; then
      echo "* $path"
    fi
  done
  echo
  echo "Check that the following is true and try again:"
  echo "* An Intel oneAPI Toolkit $oneapiVersion is installed - oneAPI for"
  echo "  $oneapiProduct GPUs can only be installed within an existing Toolkit"
  echo "  with a matching version."
  echo "* If the Toolkit is installed somewhere other than $HOME/intel/oneapi"
  echo "  or /opt/intel/oneapi, set the ONEAPI_ROOT environment variable or"
  echo "  pass the --install-dir argument to this script."
  echo
  exit 1
}

getUserApprovalOrExit() {
  if [ "$promptUser" = 'yes' ]; then
    echo "$1 Proceed? [Yn]: "

    read -r line
    case "$line" in
      n* | N*)
        exit 0
    esac
  fi
}

installPackage() {
  getUserApprovalOrExit "The package will be installed in $oneapiRoot/."

  libDestDir="$oneapiRoot/compiler/$oneapiVersion/lib/"

  installedAny='no'
  for root in "$payloadDir" "$payloadDirFallback"; do
    if [ "$root" = '' ] || [ ! -d "$root" ]; then
      continue
    fi

    for candidate in "$root/lib" "$root/lib64" "$root"; do
      if [ ! -d "$candidate" ]; then
        continue
      fi

      # Copy any libur*.so* files (including symlinks) if present.
      set -- "$candidate"/libur*.so*
      if [ -e "$1" ]; then
        checkCmd 'cp' '-a' "$candidate"/libur*.so* "$libDestDir"
        installedAny='yes'
      fi
    done
  done

  if [ "$installedAny" != 'yes' ]; then
    echo "Error: no libur*.so* files found in embedded payload."
    exit 1
  fi

  # Also refresh symlinks in the Toolkit-wide lib dir (INSTALL_DIR/$oneapiVersion/lib).
  # This mirrors the typical oneAPI layout used by setvars.
  rootLibDir="$oneapiRoot/$oneapiVersion/lib"
  if [ -d "$oneapiRoot/$oneapiVersion" ]; then
    checkCmd 'mkdir' '-p' "$rootLibDir"

    # For each fully-versioned library, create/refresh the local symlink chain:
    #   libX.so -> libX.so.<MAJOR> -> libX.so.<MAJOR>.<MINOR>.<PATCH>
    # and link the fully-versioned file back to compiler/$oneapiVersion/lib.
    set -- "$libDestDir"/libur*.so.[0-9]*.[0-9]*.[0-9]*
    if [ -e "$1" ]; then
      for verPath in "$libDestDir"/libur*.so.[0-9]*.[0-9]*.[0-9]*; do
        verFile=$(basename "$verPath")
        major=$(echo "$verFile" | sed -E 's/.*\.so\.([0-9]+)\..*/\1/')
        soname=$(echo "$verFile" | sed -E "s/\.so\.[0-9]+\..*/.so.$major/")
        unversioned=$(echo "$verFile" | sed -E 's/\.so\..*/.so/')

        checkCmd 'ln' '-sf' "../../compiler/$oneapiVersion/lib/$verFile" "$rootLibDir/$verFile"
        checkCmd 'ln' '-sf' "./$verFile" "$rootLibDir/$soname"
        checkCmd 'ln' '-sf' "./$soname" "$rootLibDir/$unversioned"
      done
    fi
  fi

  # Ensure CUDA adapter soname/unversioned symlinks exist even if the payload
  # only shipped the fully-versioned .so.
  if [ -f "$libDestDir/$urAdapterVersioned" ]; then
    checkCmd 'ln' '-sf' "$urAdapterVersioned" "$libDestDir/$urAdapterSoname"
    checkCmd 'ln' '-sf' "$urAdapterSoname" "$libDestDir/$urAdapterUnversioned"
  fi

  echo "* Unified Runtime libraries installed in $libDestDir."

  if [ "$cleanupPayloadDir" = 'yes' ] && [ "$payloadDir" != '' ]; then
    checkCmd 'rm' '-r' "$payloadDir"
  fi
  if [ "$cleanupPayloadDirFallback" = 'yes' ] && [ "$payloadDirFallback" != '' ]; then
    checkCmd 'rm' '-r' "$payloadDirFallback"
  fi

  echo
  echo "Installation complete."
  echo
}

printHelpAndExit() {
  scriptName=$(basename "$0")
  echo "Usage: $scriptName [options]"
  echo
  echo "Options:"
  echo "  -f, --extract-folder PATH"
  echo "    Set the extraction folder where the package contents will be saved."
  echo "  -h, --help"
  echo "    Show this help message."
  echo "  -i, --install-dir INSTALL_DIR"
  echo "    Customize the installation directory. INSTALL_DIR must be the root"
  echo "    of an Intel oneAPI Toolkit $oneapiVersion installation i.e. the "
  echo "    directory containing compiler/$oneapiVersion."
  echo "  -p, --pack LIB_DIR"
  echo "    Rebuild the embedded archive from LIB_DIR/libur*.so* and update"
  echo "    the archive checksum in-place. Does not install anything."
  echo "  -u, --uninstall"
  echo "    Remove a previous installation of this product - does not remove the"
  echo "    Intel oneAPI Toolkit installation."
  echo "  -x, --extract-only"
  echo "    Unpack the installation package only - do not install the product."
  echo "  -y, --yes"
  echo "    Install or uninstall without prompting the user for confirmation."
  echo
  exit 1
}

uninstallPackage() {
  getUserApprovalOrExit "oneAPI for $oneapiProduct GPUs will be uninstalled from $oneapiRoot/."

  checkCmd 'rm' '-f' "$oneapiRoot/compiler/$oneapiVersion/lib/$urAdapterUnversioned"
  checkCmd 'rm' '-f' "$oneapiRoot/compiler/$oneapiVersion/lib/$urAdapterSoname"
  checkCmd 'rm' '-f' "$oneapiRoot/compiler/$oneapiVersion/lib/$urAdapterVersioned"
  echo "* $backendPrintable Unified Runtime adapter removed."

  if [ -d "$oneapiRoot/intelpython" ]; then
    pythonDir="$oneapiRoot/intelpython/python3.9"
    checkCmd 'rm' '-f' "$pythonDir/lib/$urAdapterUnversioned"
    checkCmd 'rm' '-f' "$pythonDir/lib/$urAdapterSoname"
    checkCmd 'rm' '-f' "$pythonDir/lib/$urAdapterVersioned"
    checkCmd 'rm' '-f' "$pythonDir/envs/$oneapiVersion/lib/$urAdapterUnversioned"
    checkCmd 'rm' '-f' "$pythonDir/envs/$oneapiVersion/lib/$urAdapterSoname"
    checkCmd 'rm' '-f' "$pythonDir/envs/$oneapiVersion/lib/$urAdapterVersioned"
  fi

  checkCmd 'rm' '-f' "$oneapiRoot/licensing/$oneapiVersion/LICENSE_oneAPI_for_${oneapiProduct}_GPUs.md"
  echo '* License removed.'

  echo
  echo "Uninstallation complete."
  echo
}

oneapiProduct='NVIDIA'
oneapiBackend='cuda'
oneapiVersion='2025.3'

urAdapterVersioned='libur_adapter_cuda.so.0.12.0'
urAdapterSoname='libur_adapter_cuda.so.0'
urAdapterUnversioned='libur_adapter_cuda.so'

archiveChecksum='b5c85378904e16ad5df1ab5678123c8ea1c176ccc9ac5157e958e8367f9cd2583b3510804a42fb315bb6cdd02dca2f4c'

backendPrintable=$(echo "$oneapiBackend" | tr '[:lower:]' '[:upper:]')

extractOnly='no'
oneapiRoot=''
promptUser='yes'
tempDir=''
uninstall='no'
packLibDir=''

# Use local install artifacts (if present) instead of the embedded archive.
# Default is relative to this installer script so it works even under sudo.
# Override with CUDA_PLUGINS_LLVM_INSTALL_DIR.
scriptDir=$(dirname "$(readlink -f "$0")")
llvmInstallDirDefault="$scriptDir/llvm/_install"
llvmInstallDir=${CUDA_PLUGINS_LLVM_INSTALL_DIR:-"$llvmInstallDirDefault"}
payloadDir=''
payloadDirFallback=''
cleanupPayloadDir='no'
cleanupPayloadDirFallback='no'

releaseType=''
if [ "$oneapiProduct" = 'AMD' ]; then
  releaseType='(beta) '
fi

# needed?
echo
echo "oneAPI for $oneapiProduct GPUs ${releaseType}${oneapiVersion} (CUDA ${cudaToolkitVersion}) installer"
echo

# Process command-line options.
while [ $# -gt 0 ]; do
  case "$1" in
    -f | --f | --extract-folder)
      shift
      checkArgument "$1"
      if [ -f "$1" ]; then
        echo "Error: extraction folder path '$1' is a file."
        echo
        exit 1
      fi
      tempDir="$1"
      ;;
    -h | --h | --help)
      printHelpAndExit
      ;;
    -i | --i | --install-dir)
      shift
      checkArgument "$1"
      oneapiRoot="$1"
      ;;
    -p | --p | --pack)
      shift
      checkArgument "$1"
      packLibDir="$1"
      ;;
    -u | --u | --uninstall)
      uninstall='yes'
      ;;
    -x | --x | --extract-only)
      extractOnly='yes'
      ;;
    -y | --y | --yes)
      promptUser='no'
      ;;
    *)
      printHelpAndExit
      ;;
  esac
  shift
done

# Maintenance mode: rebuild embedded archive and exit.
if [ "$packLibDir" != '' ]; then
  repackInstallerFromLibDirOrExit "$packLibDir"
  exit 0
fi

# Check for invalid combinations of options.
if [ "$extractOnly" = 'yes' ] && [ "$oneapiRoot" != '' ]; then
  echo "--install-dir argument ignored due to --extract-only."
elif [ "$uninstall" = 'yes' ] && [ "$extractOnly" = 'yes' ]; then
  echo "--extract-only argument ignored due to --uninstall."
elif [ "$uninstall" = 'yes' ] && [ "$tempDir" != '' ]; then
  echo "--extract-folder argument ignored due to --uninstall."
fi

# Find the existing Intel oneAPI Toolkit installation.
if [ "$extractOnly" = 'no' ]; then
  if [ "$oneapiRoot" != '' ]; then
    findOneapiRootOrExit "$oneapiRoot"
  else
    findOneapiRootOrExit "$ONEAPI_ROOT" "$HOME/intel/oneapi" "/opt/intel/oneapi"
  fi

  if [ ! -w "$oneapiRoot" ]; then
    echo "Error: no write permissions for the Intel oneAPI Toolkit root folder."
    echo "Please check your permissions and/or run this command again with sudo."
    echo
    exit 1
  fi
fi

if [ "$uninstall" = 'yes' ]; then
  uninstallPackage
else
  extractPackage

  if [ "$extractOnly" = 'yes' ]; then
    echo "Package extracted to $tempDir."
    echo "Installation skipped."
    echo
  else
    installPackage
  fi
fi

# Exit from the script here to avoid trying to interpret the archive as part of
# the script.
exit 0

__ARCHIVE__

